typedef struct Evictor Evictor;
struct Evictor {
    const char *(*pick)(Evictor *self, const char **keys, size_t n);
    void *state;
};
typedef struct Cache { Evictor evict; size_t n; const char **keys; } Cache;

static const char *lru_pick(Evictor *self, const char **keys, size_t n) {
    (void)self; (void)n; return keys[0];
}
static const Evictor LRU = { .pick = lru_pick, .state = NULL };
void cache_init(Cache *c, Evictor policy) { c->evict = policy; }

